#include <bits/stdc++.h>
using namespace std;

vector<int> primef(int n) {
    vector<int> factors;
    for (int i = 2; 1LL * i * i <= n; ++i) {
        while (n % i == 0) {
            factors.push_back(i);
            n /= i;
        }
    }
    if (n > 1) factors.push_back(n);
    return factors;
}

int main() {
    int a, b;
    cin >> a >> b;

    vector<int> m = primef(b);
    cout << m.size();

    return 0;
}

